spec.expr:
max by (instance) (
  node_thermal_zone_temp{
    dashboard_instance=~"$dashboard_instance",
    type=~"cpu.*"
  }
)
or
max by (instance) (
  node_hwmon_temp_celsius{
    dashboard_instance=~"$dashboard_instance",
    chip_name=~"coretemp|k10temp|cpu_thermal|zenpower"
    }
)
or
max by (instance) (
  node_hwmon_temp_celsius{
    dashboard_instance=~"$dashboard_instance"
  }
)

(
  (node_filesystem_size_bytes{instance="$node", job="$job", mountpoint="/", fstype!="rootfs"}
   - node_filesystem_avail_bytes{instance="$node", job="$job", mountpoint="/", fstype!="rootfs"})
  / node_filesystem_size_bytes{instance="$node", job="$job", mountpoint="/", fstype!="rootfs"}
) * 100

max by (instance) (
  node_thermal_zone_temp{
    instance="$node",
    job="$job",
    type=~"cpu.*"
  }
)
or
max by (instance) (
  node_hwmon_temp_celsius{
    instance="$node",
    job="$job",
    chip_name=~"coretemp|k10temp|cpu_thermal|zenpower"
    }
)
or
max by (instance) (
  node_hwmon_temp_celsius{
    instance="$node",
    job="$job"
  }
)
